create extension if not exists pgcrypto;
create type public.app_role as enum ('super_admin','admin','manager','salesperson','marketing','finance','viewer');
create type public.lead_status as enum ('new','contacted','qualified','unqualified','converted','lost');
create type public.opportunity_status as enum ('open','won','lost');
create type public.task_status as enum ('pending','in_progress','completed','cancelled');
create type public.activity_type as enum ('call','email','whatsapp','meeting','note','proposal','other');

create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null, phone text, role public.app_role not null default 'viewer', avatar_url text, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.organizations (id uuid primary key default gen_random_uuid(), name text not null, industry text, phone text, email text, website text, address text, city text, country text default 'Uganda', notes text, assigned_to uuid references public.profiles(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.contacts (id uuid primary key default gen_random_uuid(), organization_id uuid references public.organizations(id) on delete set null, first_name text not null, last_name text, job_title text, phone text, email text, address text, city text, country text default 'Uganda', source text, assigned_to uuid references public.profiles(id) on delete set null, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.lead_sources (id uuid primary key default gen_random_uuid(), name text not null unique, description text, created_at timestamptz not null default now());
create table public.leads (id uuid primary key default gen_random_uuid(), organization_id uuid references public.organizations(id) on delete set null, contact_id uuid references public.contacts(id) on delete set null, name text not null, company_name text, phone text, email text, location text, source_id uuid references public.lead_sources(id) on delete set null, product_service text, status public.lead_status not null default 'new', score integer not null default 0 check (score between 0 and 100), assigned_to uuid references public.profiles(id) on delete set null, next_follow_up_at timestamptz, notes text, converted_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.pipeline_stages (id uuid primary key default gen_random_uuid(), name text not null unique, position integer not null unique, probability numeric(5,2) not null default 0 check (probability between 0 and 100), is_won boolean not null default false, is_lost boolean not null default false, created_at timestamptz not null default now());
create table public.opportunities (id uuid primary key default gen_random_uuid(), lead_id uuid references public.leads(id) on delete set null, organization_id uuid references public.organizations(id) on delete set null, contact_id uuid references public.contacts(id) on delete set null, title text not null, value numeric(14,2) not null default 0 check (value >= 0), currency text not null default 'UGX', stage_id uuid references public.pipeline_stages(id) on delete set null, status public.opportunity_status not null default 'open', probability numeric(5,2) not null default 0 check (probability between 0 and 100), expected_close_date date, assigned_to uuid references public.profiles(id) on delete set null, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.activities (id uuid primary key default gen_random_uuid(), lead_id uuid references public.leads(id) on delete cascade, opportunity_id uuid references public.opportunities(id) on delete cascade, contact_id uuid references public.contacts(id) on delete cascade, organization_id uuid references public.organizations(id) on delete cascade, type public.activity_type not null, subject text not null, description text, activity_at timestamptz not null default now(), created_by uuid references public.profiles(id) on delete set null, created_at timestamptz not null default now());
create table public.tasks (id uuid primary key default gen_random_uuid(), title text not null, description text, task_type public.activity_type not null default 'other', lead_id uuid references public.leads(id) on delete cascade, opportunity_id uuid references public.opportunities(id) on delete cascade, contact_id uuid references public.contacts(id) on delete cascade, organization_id uuid references public.organizations(id) on delete cascade, assigned_to uuid references public.profiles(id) on delete set null, due_at timestamptz, status public.task_status not null default 'pending', completed_at timestamptz, created_by uuid references public.profiles(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.campaigns (id uuid primary key default gen_random_uuid(), name text not null, channel text, start_date date, end_date date, budget numeric(14,2) not null default 0 check (budget >= 0), currency text not null default 'UGX', notes text, created_by uuid references public.profiles(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.campaign_leads (campaign_id uuid not null references public.campaigns(id) on delete cascade, lead_id uuid not null references public.leads(id) on delete cascade, created_at timestamptz not null default now(), primary key (campaign_id, lead_id));
create table public.products_services (id uuid primary key default gen_random_uuid(), name text not null, description text, category text, unit_price numeric(14,2) not null default 0 check (unit_price >= 0), currency text not null default 'UGX', is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.documents (id uuid primary key default gen_random_uuid(), file_name text not null, storage_path text not null, mime_type text, file_size bigint, lead_id uuid references public.leads(id) on delete cascade, opportunity_id uuid references public.opportunities(id) on delete cascade, contact_id uuid references public.contacts(id) on delete cascade, organization_id uuid references public.organizations(id) on delete cascade, uploaded_by uuid references public.profiles(id) on delete set null, created_at timestamptz not null default now());
create table public.notes (id uuid primary key default gen_random_uuid(), content text not null, lead_id uuid references public.leads(id) on delete cascade, opportunity_id uuid references public.opportunities(id) on delete cascade, contact_id uuid references public.contacts(id) on delete cascade, organization_id uuid references public.organizations(id) on delete cascade, created_by uuid references public.profiles(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.audit_logs (id uuid primary key default gen_random_uuid(), user_id uuid references public.profiles(id) on delete set null, action text not null, table_name text, record_id uuid, old_data jsonb, new_data jsonb, created_at timestamptz not null default now());

create index idx_contacts_org on public.contacts(organization_id);
create index idx_leads_status on public.leads(status);
create index idx_leads_assigned on public.leads(assigned_to);
create index idx_leads_followup on public.leads(next_follow_up_at);
create index idx_opportunities_stage on public.opportunities(stage_id);
create index idx_opportunities_assigned on public.opportunities(assigned_to);
create index idx_tasks_assigned_due on public.tasks(assigned_to, due_at);
create index idx_activities_activity_at on public.activities(activity_at desc);

insert into public.pipeline_stages (name, position, probability, is_won, is_lost) values ('New',1,10,false,false),('Contacted',2,20,false,false),('Qualified',3,40,false,false),('Proposal',4,60,false,false),('Negotiation',5,80,false,false),('Won',6,100,true,false),('Lost',7,0,false,true);
insert into public.lead_sources (name) values ('Website'),('WhatsApp'),('Phone'),('Referral'),('Social Media'),('Walk-in'),('Email'),('Other');

alter table public.profiles enable row level security;
alter table public.organizations enable row level security;
alter table public.contacts enable row level security;
alter table public.lead_sources enable row level security;
alter table public.leads enable row level security;
alter table public.pipeline_stages enable row level security;
alter table public.opportunities enable row level security;
alter table public.activities enable row level security;
alter table public.tasks enable row level security;
alter table public.campaigns enable row level security;
alter table public.campaign_leads enable row level security;
alter table public.products_services enable row level security;
alter table public.documents enable row level security;
alter table public.notes enable row level security;
alter table public.audit_logs enable row level security;

create or replace function public.is_admin_or_manager() returns boolean language sql stable security definer set search_path = public as $$ select exists (select 1 from public.profiles where id = auth.uid() and role in ('super_admin','admin','manager')); $$;
create policy profiles_self_or_manager on public.profiles for select to authenticated using (id = auth.uid() or public.is_admin_or_manager());
create policy profiles_update_manager on public.profiles for update to authenticated using (id = auth.uid() or public.is_admin_or_manager()) with check (id = auth.uid() or public.is_admin_or_manager());
create policy org_read on public.organizations for select to authenticated using (true);
create policy org_write on public.organizations for all to authenticated using (public.is_admin_or_manager() or assigned_to = auth.uid()) with check (public.is_admin_or_manager() or assigned_to = auth.uid());
create policy contacts_read on public.contacts for select to authenticated using (true);
create policy contacts_write on public.contacts for all to authenticated using (public.is_admin_or_manager() or assigned_to = auth.uid()) with check (public.is_admin_or_manager() or assigned_to = auth.uid());
create policy sources_read on public.lead_sources for select to authenticated using (true);
create policy sources_manage on public.lead_sources for all to authenticated using (public.is_admin_or_manager()) with check (public.is_admin_or_manager());
create policy leads_read on public.leads for select to authenticated using (true);
create policy leads_write on public.leads for all to authenticated using (public.is_admin_or_manager() or assigned_to = auth.uid()) with check (public.is_admin_or_manager() or assigned_to = auth.uid());
create policy stages_read on public.pipeline_stages for select to authenticated using (true);
create policy stages_manage on public.pipeline_stages for all to authenticated using (public.is_admin_or_manager()) with check (public.is_admin_or_manager());
create policy opp_read on public.opportunities for select to authenticated using (true);
create policy opp_write on public.opportunities for all to authenticated using (public.is_admin_or_manager() or assigned_to = auth.uid()) with check (public.is_admin_or_manager() or assigned_to = auth.uid());
create policy activities_read on public.activities for select to authenticated using (true);
create policy activities_write on public.activities for all to authenticated using (public.is_admin_or_manager() or created_by = auth.uid());
create policy tasks_read on public.tasks for select to authenticated using (public.is_admin_or_manager() or assigned_to = auth.uid() or created_by = auth.uid());
create policy tasks_write on public.tasks for all to authenticated using (public.is_admin_or_manager() or assigned_to = auth.uid() or created_by = auth.uid()) with check (public.is_admin_or_manager() or assigned_to = auth.uid() or created_by = auth.uid());
create policy campaigns_read on public.campaigns for select to authenticated using (true);
create policy campaigns_write on public.campaigns for all to authenticated using (public.is_admin_or_manager() or created_by = auth.uid()) with check (public.is_admin_or_manager() or created_by = auth.uid());
create policy campaign_leads_read on public.campaign_leads for select to authenticated using (true);
create policy campaign_leads_write on public.campaign_leads for all to authenticated using (public.is_admin_or_manager());
create policy products_read on public.products_services for select to authenticated using (true);
create policy products_write on public.products_services for all to authenticated using (public.is_admin_or_manager()) with check (public.is_admin_or_manager());
create policy documents_read on public.documents for select to authenticated using (true);
create policy documents_write on public.documents for all to authenticated using (public.is_admin_or_manager() or uploaded_by = auth.uid()) with check (public.is_admin_or_manager() or uploaded_by = auth.uid());
create policy notes_read on public.notes for select to authenticated using (true);
create policy notes_write on public.notes for all to authenticated using (public.is_admin_or_manager() or created_by = auth.uid()) with check (public.is_admin_or_manager() or created_by = auth.uid());
create policy audit_read on public.audit_logs for select to authenticated using (public.is_admin_or_manager());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.profiles (id, full_name) values (new.id, coalesce(new.raw_user_meta_data->>'full_name', new.email, 'User')); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();;
